import json
import pathlib
import re
import sys


EXPECTED_NAMES = {
    'אתחול סביבת WebView2 late background boot after navigation cannot change options or flush events',
    'אתחול סביבת WebView2 late background boot after crash and retry cannot change options or flush events',
}
ASSERTION_LINE = 882
ASSERTION = re.compile(
    r"Expected:\s*empty\s*\n\s*Actual:\s*Set:\['theme\.changed'\]"
)
INFRASTRUCTURE_OR_FIXTURE = re.compile(
    r'Found 0 widgets|exactly one matching candidate|TimeoutException|timed out|'
    r'Dart compiler|Compilation failed|compilation error|Failed to load|'
    r'NoSuchMethodError|MissingPluginException|LateInitializationError|'
    r'TypeError|Bad state:|Guarded function conflict|Out of memory|'
    r'out of memory|SocketException',
    re.IGNORECASE,
)


def verify(records, exit_code):
    assert exit_code == 1, f'Unexpected Flutter exit code: {exit_code}'
    completed = [record for record in records if record.get('type') == 'done']
    assert len(completed) == 1 and completed[0].get('success') is False, (
        'Reporter did not finish a failing run'
    )
    tests = {
        record['test']['id']: record['test']
        for record in records
        if record.get('type') == 'testStart'
    }
    selected = {
        test_id: test
        for test_id, test in tests.items()
        if test['name'] in EXPECTED_NAMES
    }
    assert len(selected) == 2, f'Expected two distinct host cases, got {selected}'
    assert {test['name'] for test in selected.values()} == EXPECTED_NAMES
    endings = {
        record['testID']: record
        for record in records
        if record.get('type') == 'testDone'
    }
    failures = {
        test_id
        for test_id, end in endings.items()
        if end.get('result') in ('failure', 'error')
    }
    assert failures == set(selected), f'Unexpected failures: {failures - set(selected)}'
    all_errors = [record for record in records if record.get('type') == 'error']
    assert all(record.get('testID') in selected for record in all_errors), (
        'Compilation, loading, or teardown failed outside the selected cases'
    )
    all_messages = '\n'.join(
        str(record.get('message', '')) + '\n' + str(record.get('error', ''))
        for record in records
    )
    rejected = INFRASTRUCTURE_OR_FIXTURE.search(all_messages)
    assert rejected is None, f'Infrastructure/fixture failure: {rejected.group()}'
    for test_id, test in selected.items():
        end = endings[test_id]
        assert end.get('skipped') is False and end.get('hidden') is False
        assert test.get('metadata', {}).get('skip') is False
        source = test.get('root_url') or test.get('url', '')
        assert source.endswith('/test/plugins/view/plugin_background_host_test.dart')
        errors = [record for record in all_errors if record.get('testID') == test_id]
        assert len(errors) == 1, f'Multiple errors in {test["name"]}: {errors}'
        messages = '\n'.join(
            str(record.get('message', '')) + '\n' + str(record.get('error', ''))
            for record in records
            if record.get('testID') == test_id
        )
        assert 'TestFailure was thrown running a test' in messages, test['name']
        assert ASSERTION.search(messages), f'Wrong Expected/Actual in {test["name"]}'
        assert f'plugin_background_host_test.dart line {ASSERTION_LINE}' in messages, (
            f'Failure was not the old-boot event-options assertion: {test["name"]}'
        )
    return sorted(EXPECTED_NAMES)


if __name__ == '__main__':
    records = [
        json.loads(line)
        for line in pathlib.Path(sys.argv[1]).read_text().splitlines()
        if line.strip()
    ]
    confirmed = verify(records, int(sys.argv[2]))
    print(json.dumps({'confirmed_late_boot_regressions': confirmed}, ensure_ascii=False))
